 void add(){content.addView(title("Repas et aliments"));LinearLayout actions=card();Button m=b("+ Ajouter un repas");m.setOnClickListener(v->mealDialog(null));actions.addView(m,new LinearLayout.LayoutParams(-1,dp(50)));Button f=small("Créer un aliment",ORANGE);f.setOnClickListener(v->foodDialog());LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(46));fp.setMargins(0,dp(8),0,0);actions.addView(f,fp);Button r=small("Créer une recette / un plat",DARK);r.setOnClickListener(v->recipeDialog());LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(46));rp.setMargins(0,dp(8),0,0);actions.addView(r,rp);content.addView(actions);content.addView(t("Base alimentaire",19,true));foodBrowser(content);}
 void foodBrowser(LinearLayout root){LinearLayout tools=card();Spinner cats=new Spinner(this);cats.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.categories()));tools.addView(t("Catégorie",13,true));tools.addView(cats);LinearLayout searchLine=new LinearLayout(this);AutoCompleteTextView search=new AutoCompleteTextView(this);search.setHint("Rechercher par nom, catégorie ou plusieurs mots…");search.setThreshold(0);search.setSingleLine();search.setBackground(shape(BG,10));search.setPadding(dp(10),dp(8),dp(10),dp(8));Button clear=small("×",Color.GRAY);searchLine.addView(search,new LinearLayout.LayoutParams(0,dp(48),1));searchLine.addView(clear,new LinearLayout.LayoutParams(dp(48),dp(48)));tools.addView(searchLine);root.addView(tools);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);root.addView(results);Runnable refresh=()->{String cat=(String)cats.getSelectedItem();List<NutriDb.Food> fs=db.foodsFiltered(search.getText().toString(),cat);ArrayList<String> names=new ArrayList<>();for(NutriDb.Food x:fs)names.add(x.name);search.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_dropdown_item_1line,names));results.removeAllViews();if(fs.isEmpty())results.addView(t("Aucun aliment trouvé.",14,false));for(NutriDb.Food x:fs){LinearLayout c=card();TextView name=t(x.name,15,true),detail=t(foodDetail(x),13,false);detail.setVisibility(View.GONE);name.setCompoundDrawablesWithIntrinsicBounds(0,0,android.R.drawable.arrow_down_float,0);name.setOnClickListener(v->detail.setVisibility(detail.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));c.addView(name);c.addView(detail);results.addView(c);}};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){refresh.run();}public void afterTextChanged(Editable e){}});cats.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){refresh.run();}});clear.setOnClickListener(v->{search.setText("");cats.setSelection(0);});refresh.run();}
 String foodDetail(NutriDb.Food x){return (x.categories.isEmpty()?"":x.categories+"\n")+"Pour 100 g / unité indiquée : "+Math.round(x.cal)+" kcal\nProtéines : "+x.protein+" g   ·   Glucides : "+x.carbs+" g\nLipides : "+x.fat+" g   ·   Fibres : "+x.fiber+" g"+(x.sugar>0?"   ·   Sucres : "+x.sugar+" g":"");}
