 void mealDialog(NutriDb.Meal existing){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(8),dp(4),dp(8),dp(10));EditText date=labeled(l,"Date",existing==null?LocalDate.now().toString():existing.date,"AAAA-MM-JJ"),time=labeled(l,"Heure",existing==null?LocalTime.now().withSecond(0).withNano(0).toString():existing.time,"HH:mm"),meal=labeled(l,"Nom du repas",existing==null?"Déjeuner":existing.meal,"");l.addView(t("Type",13,true));Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Aliment","Recette"}));l.addView(type);LinearLayout pickBox=new LinearLayout(this);pickBox.setOrientation(LinearLayout.VERTICAL);l.addView(pickBox);final Picker[] picker={null};final Spinner[] recipe={null};EditText qty=labeled(l,"Quantité consommée",existing==null?"100":""+amountNum(existing.amount,100),"g ou parts");Runnable buildPicker=()->{pickBox.removeAllViews();if(type.getSelectedItemPosition()==0){picker[0]=foodPicker(pickBox);if(existing!=null)picker[0].search.setText(existing.item);}else{pickBox.addView(t("Recette sélectionnée",13,true));recipe[0]=new Spinner(this);recipe[0].setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.recipes()));pickBox.addView(recipe[0]);if(existing!=null){List<NutriDb.Recipe> rs=db.recipes();for(int i=0;i<rs.size();i++)if(rs.get(i).name.equals(existing.item))recipe[0].setSelection(i);}}};type.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){if(existing==null)qty.setText(i==0?"100":"1");buildPicker.run();}});if(existing!=null){boolean rec=false;for(NutriDb.Recipe r:db.recipes())if(r.name.equals(existing.item))rec=true;type.setSelection(rec?1:0);}buildPicker.run();new AlertDialog.Builder(this).setTitle(existing==null?"Ajouter un repas":"Modifier le repas").setView(scroll(l)).setNegativeButton("Annuler",null).setPositiveButton(existing==null?"Ajouter":"Enregistrer",(d,w)->{double q=n(qty,1);String itemName=null,amount=null;NutriDb.Nutrients nn=null;if(type.getSelectedItemPosition()==0&&picker[0]!=null){NutriDb.Food f=(NutriDb.Food)picker[0].item.getSelectedItem();if(f!=null){itemName=f.name;amount=q+" g";nn=new NutriDb.Nutrients(f.cal,f.protein,f.fat,f.carbs,f.fiber,f.sugar).scale(q/100);}}else if(recipe[0]!=null){NutriDb.Recipe r=(NutriDb.Recipe)recipe[0].getSelectedItem();if(r!=null){itemName=r.name;amount=q+" part(s)";nn=new NutriDb.Nutrients(r.cal,r.protein,r.fat,r.carbs,r.fiber,r.sugar).scale(q);}}if(nn!=null){if(existing==null)db.addMeal(profile.id,date.getText().toString(),time.getText().toString(),meal.getText().toString(),itemName,amount,nn);else db.updateMeal(existing.id,profile.id,date.getText().toString(),time.getText().toString(),meal.getText().toString(),itemName,amount,nn);}tab=0;render();}).show();}
 void foodDialog(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText name=labeled(l,"Nom de l'aliment","",""),brand=labeled(l,"Marque (optionnel)","",""),cats=labeled(l,"Catégories séparées par des virgules","","ex. Fruits,Desserts"),cal=labeled(l,"Calories pour 100 g","0","kcal"),pro=labeled(l,"Protéines pour 100 g","0","g"),fat=labeled(l,"Lipides pour 100 g","0","g"),carb=labeled(l,"Glucides pour 100 g","0","g"),fib=labeled(l,"Fibres pour 100 g","0","g"),sug=labeled(l,"Sucres pour 100 g","0","g");new AlertDialog.Builder(this).setTitle("Nouvel aliment").setView(scroll(l)).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(d,w)->{if(name.length()>0)db.saveFood(new NutriDb.Food(0,name.getText().toString(),brand.getText().toString(),cats.getText().toString(),n(cal,0),n(pro,0),n(fat,0),n(carb,0),n(fib,0),n(sug,0)));render();}).show();}
 void recipeDialog(){ArrayList<NutriDb.Ingredient> ins=new ArrayList<>();LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(8),0,dp(8),dp(8));EditText name=labeled(l,"Nom du plat","",""),parts=labeled(l,"Nombre total de parts","4","parts");l.addView(t("Ajouter un ingrédient",16,true));Picker picker=foodPicker(l);EditText grams=labeled(l,"Quantité de cet ingrédient","100","g");Button plus=b("+ Ajouter cet ingrédient");TextView sum=t("Aucun ingrédient",13,false);l.addView(plus,new LinearLayout.LayoutParams(-1,dp(48)));l.addView(sum);plus.setOnClickListener(v->{NutriDb.Food f=(NutriDb.Food)picker.item.getSelectedItem();if(f!=null){ins.add(new NutriDb.Ingredient(f,n(grams,100)));StringBuilder s=new StringBuilder();for(NutriDb.Ingredient i:ins)s.append("• ").append(i.food.name).append(" · ").append(Math.round(i.grams)).append(" g\n");sum.setText(s.toString());}});new AlertDialog.Builder(this).setTitle("Nouvelle recette").setView(scroll(l)).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",(d,w)->{if(name.length()>0&&!ins.isEmpty())db.saveRecipe(name.getText().toString(),n(parts,1),ins);render();}).show();}
 void stats(){content.addView(title("Statistiques"));LinearLayout top=card();LinearLayout row=new LinearLayout(this);Button day=small("Journée",GREEN),a=small("7 jours",GREEN),c=small("30 jours",GREEN);row.addView(day,new LinearLayout.LayoutParams(0,dp(44),1));row.addView(a,new LinearLayout.LayoutParams(0,dp(44),1));row.addView(c,new LinearLayout.LayoutParams(0,dp(44),1));top.addView(row);content.addView(top);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);content.addView(box);day.setOnClickListener(v->dayCharts(box));a.setOnClickListener(v->charts(box,7));c.setOnClickListener(v->charts(box,30));dayCharts(box);}
 String unit(int i){return i==0?"kcal":"g";} String[] metricNames(){return new String[]{"Calories","Protéines","Glucides","Lipides","Fibres","Sucres"};} double[] goals(){return new double[]{profile.cal,profile.protein,profile.carbs,profile.fat,profile.fiber,profile.sugar};}
 void dayCharts(LinearLayout box){box.removeAllViews();box.addView(t("Aujourd'hui · évolution de 00:00 à 24:00",16,true));List<NutriDb.HourStat>s=db.hourlyCumulative(profile.id,LocalDate.now().toString());String[] names=metricNames();double[] goals=goals();for(int i=0;i<6;i++){box.addView(t(names[i]+" ("+unit(i)+")",16,true));box.addView(new HourChart(this,s,i,goals[i],unit(i)),new LinearLayout.LayoutParams(-1,dp(190)));}box.addView(t("Tous les apports · % de l'objectif journalier",16,true));box.addView(new PercentHourChart(this,s,goals),new LinearLayout.LayoutParams(-1,dp(230)));}
